"use strict";exports.id=843,exports.ids=[843],exports.modules={15843:(a,b,c)=>{c.d(b,{R:()=>d});let d=[{id:"BK-001",slug:"shambala-book",title:{en:"The Shambala Book",ta:"தி ஷாம்பாலா நூல் (The Shambala Book)"},tagline:{en:"Principles of Higher Consciousness, Meditative Mind, and Inner Awakening",ta:"உயர்ந்த விழிப்புணர்வு, தியான மனம் மற்றும் உள்முக விழிப்புக்கான தத்துவ வழிகாட்டி"},author:{en:"Dr. J. Arawindhan Ji (Santoshi Shri Arawindhan Ji)",ta:"முனைவர் ஜே. அரவிந்தன் ஜி (சந்தோஷி ஸ்ரீ அரவிந்தன் ஜி)"},edition:"Ecosystem & Special Retreat Edition",language:"English & Tamil",status:"Ecosystem Edition",claimId:"CLM-023",summary:{en:"The Shambala Book encapsulates over a decade of inner exploration and annual spiritual retreats held in Puducherry since 2012. It articulates the mechanics of turning from external striving toward inner stillness, outlining the Seven Chakra pyramid energy practices, Oneness Meditation, and the realization of Divine Grace in daily life.",ta:"2012 முதல் புதுச்சேரியில் நடைபெற்று வரும் மகா ஷாம்பாலா ஆன்மீக சங்கமங்களின் சாரமாக விளங்கும் நூல். புற உலக வெற்றிகளைத் தாண்டி, உள்முக அமைதியை நோக்கி நகர்வதற்கான வழிகளை விளக்குகிறது. ஏழு சக்கர பிரமிடு ஆற்றல் பயிற்சிகள், ஒருமை தியானம் மற்றும் அன்றாட வாழ்வில் ஆன்மீக விழிப்புணர்வை உணர்தல் குறித்து விரிவாகப் பேசுகிறது."},keyThemes:{en:["The Meditative Mind over mental noise","Seven Chakra energy alignment and pyramid practice","Moving from knowing to experiencing and awakening","Inner Engineering for enduring peace and conscious living"],ta:["மன இரைச்சலைத் தாண்டிய தியான மனம்","ஏழு சக்கர ஆற்றல் ஒருமுகப்படுத்தல் மற்றும் பிரமிடு பயிற்சி","அறிதலில் இருந்து அனுபவத்திற்கும் விழிப்புக்கும் நகர்தல்","நிலையான அமைதிக்கான உள்முகப் பொறியியல் (Inner Engineering)"]},targetAudience:{en:"Spiritual seekers, educators, parents, and leaders seeking holistic inner transformation.",ta:"ஆன்மீகத் தேடலுடையோர், கல்வியாளர்கள், பெற்றோர்கள் மற்றும் முழுமையான உள் அமைதியை விரும்புவோர்."},readMoreSnippet:{en:"“Do not do with your mind; do with your Meditative Mind. Outer change is temporary, shaped by circumstance. Change that begins within becomes part of who we are, and endures.”",ta:'"உங்கள் சாதாரண மனதைக் கொண்டு எதையும் செய்யாதீர்கள்; உங்கள் தியான மனதைக் கொண்டு செய்யுங்கள். வெளிப்புற மாற்றம் தற்காலிகமானது; உள்ளிருந்து தொடங்கும் மாற்றமே நிலையானது."'}},{id:"BK-002",slug:"wow-parenting-book",title:{en:"WOW Parenting",ta:"வாவ் (WOW) பேரண்டிங்"},tagline:{en:"School and Family Working as One: Because Learning Ends at Home",ta:"பள்ளியும் குடும்பமும் இணையும் தளம்: வீட்டில் மலரும் கல்வி"},author:{en:"Dr. J. Arawindhan Ji",ta:"முனைவர் ஜே. அரவிந்தன் ஜி"},edition:"1st Institutional Edition",language:"English & Tamil",status:"Published",claimId:"CLM-023",summary:{en:"A foundational handbook for contemporary parents navigating the balance between academic expectations and emotional wellbeing. WOW Parenting introduces actionable parenting styles, emotional bonding techniques, and co-schooling frameworks that help parents nurture their children’s predominant intelligences without creating stress or anxiety.",ta:"நவீன பெற்றோர்களுக்கான வழிகாட்டி நூல். கல்வி எதிர்பார்ப்புகளுக்கும் குழந்தையின் மன நலம் மற்றும் உணர்ச்சி சமநிலைக்கும் இடையிலான பாலத்தை உருவாக்குகிறது. பெற்றோர்கள் தங்கள் குழந்தைகளின் தனித்துவமான நுண்ணறிவுகளை அடையாளம் கண்டு, மன அழுத்தமின்றி அவர்களை வளர்ப்பதற்கான வழிமுறைகளை வழங்குகிறது."},keyThemes:{en:["Happy Parenting and Power Parenting methodologies","Aligning family values with classroom learning","Understanding children’s emotional spectrum and developmental phases","Building high practical self-esteem without comparison"],ta:["மகிழ்ச்சியான பெற்றோர் மற்றும் ஆற்றல்மிகு வளர்ப்பு முறைகள்","குடும்ப விழுமியங்களை பள்ளி கற்றலோடு இணைத்தல்","குழந்தைகளின் உணர்ச்சி நிலைகள் மற்றும் வளர்ச்சிப் பருவங்களைப் புரிந்துகொள்ளுதல்","மற்றவர்களோடு ஒப்பிடாமல் சுயமரியாதையை வளர்த்தல்"]},targetAudience:{en:"Parents of preschool, primary, and adolescent students.",ta:"மழலையர், தொடக்க மற்றும் வளரிளம் பருவக் குழந்தைகளின் பெற்றோர்கள்."},readMoreSnippet:{en:"“School starts at Home, continues at School, and it should end at Home, easily. When parents and teachers share the same vocabulary of encouragement, the child blossoms naturally.”",ta:'"பள்ளி வீட்டில் தொடங்குகிறது, பள்ளியில் தொடர்கிறது, மீண்டும் வீட்டில் எளிதாக முடிய வேண்டும். பெற்றோரும் ஆசிரியரும் ஒரே நேர்மறை மொழியைப் பேசும்போது குழந்தை இயல்பாக மலர்கிறது."'}},{id:"BK-003",slug:"financial-intelligence",title:{en:"Financial Intelligence (FI)",ta:"நிதி நுண்ணறிவு (Financial Intelligence)"},tagline:{en:"Resource Stewardship, Value Creation, and Practical Wealth Literacy for the Young Mind",ta:"இளம் தலைமுறைக்கான நிதி மேலாண்மை, மதிப்பு உருவாக்கம் மற்றும் நடைமுறை பொருளாதார அறிவு"},author:{en:"Dr. J. Arawindhan Ji",ta:"முனைவர் ஜே. அரவிந்தன் ஜி"},edition:"Student & Educator Edition",language:"English & Tamil",status:"Published",claimId:"CLM-023",summary:{en:"Bridging a glaring gap in traditional school curricula, this book introduces financial wisdom as an essential ninth intelligence in the Dasavadani model. From understanding the difference between earning, investing, and serving, to the psychology of money and enterprise creation, this work grounds students in ethical financial self-reliance.",ta:"பாரம்பரிய கல்வி முறைகளில் புறக்கணிக்கப்பட்ட நிதி அறிவை தசாவதானி பாடத்திட்டத்தின் ஒன்பதாவது நுண்ணறிவாக இந்நூல் அறிமுகப்படுத்துகிறது. உழைப்பு, முதலீடு, சேமிப்பு ஆகியவற்றின் வேறுபாடுகள் முதல் நேர்மையான தொழில்முனைவோர் மனநிலை வரை மாணவர்களுக்கு நடைமுறை வழிகாட்டுகிறது."},keyThemes:{en:["The 5 Ms: Mind, Material, Method, Manpower, Money","The psychology of wealth: From earning to multiplying and sharing","Student Profit Lab and micro-entrepreneurship simulations","Budgeting, capital stewardship, and ethical business creation"],ta:["5 M தத்துவம்: மனம், மூலப்பொருள், முறை, மனிதவளம், பணம்","பணத்தின் உளவியல்: ஈட்டுதல், பெருக்குதல் மற்றும் பகிர்தல்","மாணவர் லாப ஆய்வகம் (Student Profit Lab) மற்றும் குறுந்தொழில் மாதிரிகள்","வரவு-செலவு மேலாண்மை மற்றும் அறநெறி சார்ந்த தொழில் உருவாக்கம்"]},targetAudience:{en:"Middle school to college students, emerging entrepreneurs, and commerce educators.",ta:"நடுநிலைப் பள்ளி முதல் கல்லூரி மாணவர்கள், இளம் தொழில்முனைவோர் மற்றும் ஆசிரியர்கள்."},readMoreSnippet:{en:"“Money is an energy that follows clarity and discipline. When children learn to respect resources early, they grow into builders rather than mere consumers.”",ta:'"பணம் என்பது தெளிவையும் ஒழுக்கத்தையும் பின்பற்றும் ஓர் ஆற்றல். வளங்களை மதிக்க குழந்தைகள் ஆரம்பத்திலேயே கற்கும்போது, அவர்கள் நுகர்வோராக மட்டுமல்லாமல் உருவாக்குநர்களாக மாறுகிறார்கள்."'}},{id:"BK-004",slug:"emotional-intelligence",title:{en:"Emotional Intelligence (EI)",ta:"உணர்ச்சி நுண்ணறிவு (Emotional Intelligence)"},tagline:{en:"Mastering the Inner Weather: Self-Regulation, Empathy & Conscious Choice",ta:"மன உணர்வுகளை ஆளுமை செய்தல்: சுய கட்டுப்பாடு, பச்சாதாபம் மற்றும் விழிப்புணர்வுத் தேர்வுகள்"},author:{en:"Dr. J. Arawindhan Ji",ta:"முனைவர் ஜே. அரவிந்தன் ஜி"},edition:"Curriculum & Life Skills Edition",language:"English & Tamil",status:"Published",claimId:"CLM-023",summary:{en:"A core pillar of the Dasavadani curriculum, this book offers a systematic roadmap for mastering interpersonal and intrapersonal awareness. It teaches children and young adults how to convert reactivity into responsiveness, manage exam and social anxieties, and practice empathetic communication in collaborative environments.",ta:"தசாவதானி பாடத்திட்டத்தின் பத்தாவது நுண்ணறிவான உணர்ச்சி நுண்ணறிவை விளக்கும் நூல். கோபம், பயம், கவலை போன்ற உணர்வுகளை எவ்வாறு ஆக்கப்பூர்வமான ஆற்றலாக மாற்றுவது என்றும், மற்றவர்களின் உணர்வுகளை மதித்து நல்லுறவை பேணுவது எப்படி என்றும் மாணவர்களுக்கு கற்பிக்கிறது."},keyThemes:{en:["The 3C framework: Change-maker, Choice-maker, Chance-maker","The 4H integration: Heart, Hand, Head, Health","Empathy building and conflict resolution in peer groups","Mindfulness protocols for emotional balance under pressure"],ta:["3C கட்டமைப்பு: மாற்றம் உருவாக்குபவர், தேர்வு செய்பவர், வாய்ப்பு உருவாக்குபவர்","4H ஒருங்கிணைப்பு: இதயம் (Heart), கரம் (Hand), தலை (Head), உடல் நலம் (Health)","பச்சாதாபம் வளர்த்தல் மற்றும் சவால்களை சுமுகமாக தீர்த்தல்","அழுத்தமான சூழலிலும் மன அமைதி காக்கும் விழிப்புணர்வு பயிற்சிகள்"]},targetAudience:{en:"Adolescent learners, teachers, counselors, and organizational leaders.",ta:"பள்ளி-கல்லூரி மாணவர்கள், ஆசிரியர்கள், ஆலோசகர்கள் மற்றும் தலைமைப் பொறுப்பாளர்கள்."},readMoreSnippet:{en:"“IQ gets you in the door; EQ determines how far you travel. The strongest leader is not the one with the loudest voice, but the one who can master their own inner weather.”",ta:'"ஐ.கியூ (IQ) உங்களுக்கு ஒரு வாசலைத் திறக்கலாம்; ஆனால் ஈ.கியூ (EQ) மட்டுமே நீங்கள் எவ்வளவு தூரம் பயணிப்பீர்கள் என்பதை தீர்மானிக்கிறது. உண்மையான தலைவர் தன் மன உணர்வுகளை ஆளத் தெரிந்தவரே."'}},{id:"BK-005",slug:"master-stroke",title:{en:"Master Stroke",ta:"மாஸ்டர் ஸ்ட்ரோக் (Master Stroke)"},tagline:{en:"Strategic Leadership, Institutional Architecture & The Art of Execution",ta:"வியூக தலைமைத்துவம், நிறுவன கட்டமைப்பு மற்றும் திட்டங்களை வெற்றிகரமாக நிறைவேற்றும் கலை"},author:{en:"Dr. J. Arawindhan Ji",ta:"முனைவர் ஜே. அரவிந்தன் ஜி"},edition:"Executive Leadership Edition",language:"English & Tamil",status:"Published",claimId:"CLM-023",summary:{en:"Drawing on 25 years of building 18 colleges, 101 schools, and 61+ companies, Master Stroke deconstructs the science of scaling vision into reality. It details the Centre of Excellence governance model, the five-step chain of accountability, and how leaders maintain cultural coherence while expanding across states and sectors.",ta:"25 ஆண்டுகளில் 18 கல்லூரிகள், 101 பள்ளிகள் மற்றும் 61+ நிறுவனங்களை உருவாக்கிய நிஜ அனுபவங்களின் தொகுப்பு. நிறுவன மேலாண்மை, பொறுப்புணர்வு சங்கிலி, சிறப்பு மேன்மை மைய (CoE) கட்டமைப்பு மற்றும் கொள்கைகளை சமரசமின்றி பல துறைகளில் வெற்றிகரமாக விரிவுபடுத்துவது எப்படி என்பதை விளக்குகிறது."},keyThemes:{en:["Good intentions do not scale; good systems do","The Five-Step Execution Chain: Approved → Enriched → Enabled → Executed → Ensured","The Six Engines of Institutional Excellence","From Solo Founder to Self-Sustaining Ecosystem"],ta:["நல்ல எண்ணங்கள் மட்டும் விரிவடையாது; சிறந்த கட்டமைப்புகளே விரிவடையும்","ஐந்து படிநிலை செயல்பாட்டுச் சங்கிலி: ஒப்புதல் → செறிவூட்டல் → தயார்படுத்துதல் → செயல்படுத்துதல் → உறுதிசெய்தல்","நிறுவன மேன்மையின் ஆறு இயந்திரங்கள் (Six Engines)","தனிநபர் வழிகாட்டலில் இருந்து தற்சார்பு நிறுவன சூழலியலாக உருமாறுதல்"]},targetAudience:{en:"School principals, institutional founders, corporate managers, and system architects.",ta:"பள்ளி முதல்வர்கள், கல்வி நிறுவன நிறுவனர்கள், கார்ப்பரேட் மேலாளர்கள் மற்றும் நிர்வாகிகள்."},readMoreSnippet:{en:"“For doing repair work, we need to do prepare work. A master stroke in leadership is never accidental; it is the quiet result of an unbreakable daily process.”",ta:'"பழுதுபார்க்கும் வேலையைத் தவிர்க்க, நாம் முன்கூட்டியே தயாரிப்பு வேலையைச் செய்ய வேண்டும். தலைமைத்துவத்தின் மாஸ்டர் ஸ்ட்ரோக் என்பது தற்செயலானது அல்ல; அது உறுதியான தினசரி வழிமுறையின் வெளிப்பாடு."'}},{id:"BK-006",slug:"young-scientist",title:{en:"Young Scientist",ta:"இளம் விஞ்ஞானி (Young Scientist)"},tagline:{en:"Igniting Curiosity, Hands-On Experimentation & Scientific Discovery in the Classroom",ta:"வகுப்பறையில் அறிவியல் ஆர்வம், செய்முறை சோதனைகள் மற்றும் புதிய கண்டுபிடிப்புகளின் எழுச்சி"},author:{en:"Dr. J. Arawindhan Ji",ta:"முனைவர் ஜே. அரவிந்தன் ஜி"},edition:"Lab & Innovation Edition",language:"English & Tamil",status:"Published",claimId:"CLM-023",summary:{en:"Written to complement ACHARIYA’s network of 73+ LABS and Atal Tinkering Labs, Young Scientist guides educators and students through direct sensory exploration of physical laws. It advocates for inquiry-based learning where hypotheses are tested, failures are celebrated as data points, and innovation becomes a habit.",ta:"ஆச்சாரியாவின் 73+ செய்முறை ஆய்வகங்கள் மற்றும் அடல் டிங்கரிங் லேப்களின் பின்னணியில் உருவான நூல். ஏட்டுச் சுரைக்காயாக அறிவியலை படிக்காமல், குழந்தைகள் கைகளால் செய்து பார்த்து, சோதனைகள் மூலம் உண்மைகளைக் கண்டறியும் வழிமுறையை விளக்குகிறது."},keyThemes:{en:["Turning passive textbook science into living experiments","The Atal Tinkering mindset: Ideate, Prototype, Test, Iterate","Integration of robotics, green technology, and daily life science","Building observational rigor and the scientific temper"],ta:["ஏட்டுப் படிப்பை நேரடி அறிவியல் பரிசோதனைகளாக மாற்றுதல்","அடல் டிங்கரிங் மனநிலை: யோசி, மாதிரி செய், சோதித்து மேம்படுத்து","ரோபாட்டிக்ஸ், பசுமை தொழில்நுட்பம் மற்றும் அன்றாட அறிவியல்","துல்லியமான உற்றுநோக்கல் மற்றும் அறிவியல் மனப்பான்மையை வளர்த்தல்"]},targetAudience:{en:"STEM educators, young innovators, school lab coordinators, and curious students.",ta:"அறிவியல் ஆசிரியர்கள், இளம் கண்டுபிடிப்பாளர்கள் மற்றும் மாணவர் சமூகம்."},readMoreSnippet:{en:"“A child is born a natural scientist. School must never replace that wide-eyed wonder with dull formulas; it must give them the tools to test the universe.”",ta:'"ஒவ்வொரு குழந்தையும் பிறவியிலேயே ஒரு விஞ்ஞானி. பள்ளிக்கூடம் அவர்களின் வியப்பை மழுங்கடிக்காமல், இந்த பிரபஞ்சத்தை சோதித்து அறியும் கருவிகளை அவர்களின் கைகளில் கொடுக்க வேண்டும்."'}},{id:"BK-007",slug:"iravadh-book",title:{en:"Iravadh",ta:"ஐராவத் (Iravadh)"},tagline:{en:"The 21 Levels of Teacher Evolution & The Sacred Dignity of Mentorship",ta:"ஆசிரியர் பரிணாமத்தின் 21 நிலைகள் மற்றும் குருத்துவத்தின் புனித மாண்பு"},author:{en:"Dr. J. Arawindhan Ji",ta:"முனைவர் ஜே. அரவிந்தன் ஜி"},edition:"ConCardios Teacher Training Edition",language:"English & Tamil",status:"Ecosystem Edition",claimId:"CLM-023",summary:{en:"Named after the celestial elephant symbolizing steadfast strength and wisdom, Iravadh serves as the definitive manual for teacher transformation in ACHARIYA’s ConCardios training hierarchy. It maps out 21 progressive stages of teacher evolution, from a novice instructor struggling with classroom discipline to an enlightened mentor who awakens the latent genius in every student.",ta:"நிலைத்த வலிமை மற்றும் ஞானத்தின் அடையாளமான ஐராவதத்தின் பெயரால் அமைந்த இந்நூல், ஆச்சாரியாவின் கான்கார்டியோஸ் ஆசிரியர் பயிற்சிக்கான வழிகாட்டி நூலாகும். சாதாரண பயிற்றுவிப்பாளராக தொடங்கும் ஓர் ஆசிரியர், எவ்வாறு 21 நிலைகளைக் கடந்து, மாணவர்களின் உள்ளார்ந்த மேதமையை விழித்தெழச் செய்யும் ஞான குருவாக மாறுகிறார் என்பதை இந்நூல் விளக்குகிறது."},keyThemes:{en:["The 21 stages of teacher consciousness and craft mastery","Moving from instructing to inspiring and transforming","The Rope-In induction: Change, Evolve, Transcend","Creating an anxiety-free, participation-rich classroom culture"],ta:["ஆசிரியர் விழிப்புணர்வு மற்றும் கற்பித்தல் ஆளுமையின் 21 படிநிலைகள்","பாடம் நடத்துவதில் இருந்து குழந்தைகளை ஊக்கப்படுத்தி மாற்றியமைக்கும் நிலைக்கு நகர்தல்","ரோப்-இன் தத்துவம்: மாறு, பரிணமி, உன்னத நிலையை அடை","பயமற்ற, மாணவர் ஈடுபாடு நிறைந்த வகுப்பறை கலாச்சாரம் உருவாக்குதல்"]},targetAudience:{en:"School educators, teacher educators, B.Ed/D.T.Ed scholars, and academic coordinators.",ta:"பள்ளி ஆசிரியர்கள், கல்வியியல் பேராசிரியர்கள் மற்றும் ஆசிரியர் பயிற்சி மாணவர்கள்."},readMoreSnippet:{en:"“The mediocre teacher tells. The good teacher explains. The superior teacher demonstrates. The great teacher awakens. Airavatha is the journey toward awakening.”",ta:'"சாதாரண ஆசிரியர் சொல்வார்; நல்ல ஆசிரியர் விளக்குவார்; சிறந்த ஆசிரியர் செய்துகாட்டுவார்; ஆனால் மகா ஆசிரியர் விழித்தெழச் செய்வார். ஐராவத் என்பது அந்த விழிப்புணர்வு நோக்கிய பயணம்."'}}]}};